#!/usr/bin/env bash
# This code has been fully generated by an AI.
# Local & CI SFTP deployment script for waldheim.dev -> IONOS with OS Keychain integration
#
# Usage:
#   pnpm deploy                    # builds dist/ and deploys via SFTP (prompts & saves to Keychain on 1st run)
#   pnpm deploy:nobuild            # deploys existing dist/ without rebuilding
#   pnpm deploy -- --reconfigure   # updates stored credentials in the OS Keychain
#
# Supported Keychain backends (auto-detected):
#   1. WSL2 / Windows: Windows Credential Manager (Windows.Security.Credentials.PasswordVault)
#   2. Linux Desktop:  libsecret / GNOME Keyring / KWallet (secret-tool)
#   3. macOS:          macOS Keychain (security)

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
cd "${ROOT_DIR}"

KEYCHAIN_SERVICE="waldheim-homepage-deploy"
SKIP_BUILD=false
RECONFIGURE=false

for arg in "$@"; do
  case "$arg" in
    --skip-build) SKIP_BUILD=true ;;
    --reconfigure|--setup) RECONFIGURE=true ;;
  esac
done

# Detect available OS Keychain backend
detect_keychain_backend() {
  if command -v secret-tool >/dev/null 2>&1 && [[ -n "${DBUS_SESSION_BUS_ADDRESS:-}" ]]; then
    echo "secret-tool"
  elif command -v powershell.exe >/dev/null 2>&1; then
    echo "windows-vault"
  elif command -v security >/dev/null 2>&1 && [[ "$(uname -s)" == "Darwin" ]]; then
    echo "macos-keychain"
  else
    echo "none"
  fi
}

KEYCHAIN_BACKEND="$(detect_keychain_backend)"

keychain_get() {
  local key="$1"
  case "${KEYCHAIN_BACKEND}" in
    secret-tool)
      secret-tool lookup service "${KEYCHAIN_SERVICE}" key "${key}" 2>/dev/null || true
      ;;
    windows-vault)
      powershell.exe -NoProfile -NonInteractive -Command "
        try {
          \$null = [Windows.Security.Credentials.PasswordVault,Windows.Security.Credentials,ContentType=WindowsRuntime]
          \$vault = New-Object Windows.Security.Credentials.PasswordVault
          \$cred = \$vault.Retrieve('${KEYCHAIN_SERVICE}', '${key}')
          Write-Output \$cred.Password
        } catch {}
      " 2>/dev/null | tr -d '\r' || true
      ;;
    macos-keychain)
      security find-generic-password -s "${KEYCHAIN_SERVICE}" -a "${key}" -w 2>/dev/null || true
      ;;
    *)
      echo ""
      ;;
  esac
}

keychain_set() {
  local key="$1"
  local val="$2"
  case "${KEYCHAIN_BACKEND}" in
    secret-tool)
      printf '%s' "${val}" | secret-tool store --label="waldheim.dev Deploy (${key})" service "${KEYCHAIN_SERVICE}" key "${key}"
      ;;
    windows-vault)
      KEYCHAIN_VAL="${val}" powershell.exe -NoProfile -NonInteractive -Command "
        \$null = [Windows.Security.Credentials.PasswordVault,Windows.Security.Credentials,ContentType=WindowsRuntime]
        \$vault = New-Object Windows.Security.Credentials.PasswordVault
        try {
          \$old = \$vault.Retrieve('${KEYCHAIN_SERVICE}', '${key}')
          \$vault.Remove(\$old)
        } catch {}
        \$cred = New-Object Windows.Security.Credentials.PasswordCredential('${KEYCHAIN_SERVICE}', '${key}', \$env:KEYCHAIN_VAL)
        \$vault.Add(\$cred)
      " >/dev/null
      ;;
    macos-keychain)
      security add-generic-password -U -s "${KEYCHAIN_SERVICE}" -a "${key}" -w "${val}" >/dev/null
      ;;
  esac
}

# Optional fallback: load .env.deploy if present
if [[ -f "${ROOT_DIR}/.env.deploy" ]]; then
  set -a
  # shellcheck disable=SC1091
  source "${ROOT_DIR}/.env.deploy"
  set +a
fi

FTP_HOST="${FTP_HOST:-}"
FTP_USER="${FTP_USER:-}"
FTP_PASS="${FTP_PASSWORD:-${FTP_PASS:-}}"
REMOTE_DIR="${FTP_SERVER_DIR:-}"

# Read from OS Keychain if not provided via environment variables
if [[ "${RECONFIGURE}" == "false" ]] && [[ "${KEYCHAIN_BACKEND}" != "none" ]]; then
  [[ -z "${FTP_HOST}" ]] && FTP_HOST="$(keychain_get "FTP_HOST")"
  [[ -z "${FTP_USER}" ]] && FTP_USER="$(keychain_get "FTP_USER")"
  [[ -z "${FTP_PASS}" ]] && FTP_PASS="$(keychain_get "FTP_PASSWORD")"
  [[ -z "${REMOTE_DIR}" ]] && REMOTE_DIR="$(keychain_get "FTP_SERVER_DIR")"
fi

NEED_SAVE=false

if [[ "${RECONFIGURE}" == "true" ]] || [[ -z "${FTP_HOST}" ]]; then
  read -r -p "IONOS SFTP Host (FTP_HOST) [${FTP_HOST}]: " input_host
  FTP_HOST="${input_host:-${FTP_HOST}}"
  NEED_SAVE=true
fi

if [[ "${RECONFIGURE}" == "true" ]] || [[ -z "${FTP_USER}" ]]; then
  read -r -p "IONOS SFTP User (FTP_USER) [${FTP_USER}]: " input_user
  FTP_USER="${input_user:-${FTP_USER}}"
  NEED_SAVE=true
fi

if [[ "${RECONFIGURE}" == "true" ]] || [[ -z "${FTP_PASS}" ]]; then
  read -r -s -p "IONOS SFTP Password (FTP_PASSWORD): " input_pass
  echo ""
  FTP_PASS="${input_pass:-${FTP_PASS}}"
  NEED_SAVE=true
fi

if [[ "${RECONFIGURE}" == "true" ]] || [[ -z "${REMOTE_DIR}" ]]; then
  default_dir="${REMOTE_DIR:-/websites/waldheim.dev/www/}"
  if [[ "${NEED_SAVE}" == "true" ]]; then
    read -r -p "IONOS Remote Target Dir (FTP_SERVER_DIR) [${default_dir}]: " input_dir
    REMOTE_DIR="${input_dir:-${default_dir}}"
  else
    REMOTE_DIR="${default_dir}"
  fi
fi

# Persist in OS Keychain if newly entered
if [[ "${NEED_SAVE}" == "true" ]] && [[ "${KEYCHAIN_BACKEND}" != "none" ]]; then
  echo "Speichere Zugangsdaten sicher im System-Schlüsselbund (${KEYCHAIN_BACKEND}: ${KEYCHAIN_SERVICE})..."
  keychain_set "FTP_HOST" "${FTP_HOST}"
  keychain_set "FTP_USER" "${FTP_USER}"
  keychain_set "FTP_PASSWORD" "${FTP_PASS}"
  keychain_set "FTP_SERVER_DIR" "${REMOTE_DIR}"
  echo "Zugangsdaten im Schlüsselbund gespeichert."
fi

if [[ "${SKIP_BUILD}" == "false" ]] || [[ ! -d "${ROOT_DIR}/dist/_astro" ]]; then
  echo "Building production site into dist/..."
  pnpm build
fi

for asset in workbench.png print-preview.png mobile.png; do
  if [[ ! -s "dist/products/ausgabeschein-generator/${asset}" ]]; then
    echo "Error: Missing asset dist/products/ausgabeschein-generator/${asset}" >&2
    exit 1
  fi
done

if ! command -v lftp >/dev/null 2>&1; then
  echo "lftp is not installed. Installing lftp..."
  sudo apt-get update && sudo apt-get install -y lftp
fi

echo "Deploying ./dist/ to sftp://${FTP_HOST}${REMOTE_DIR} (parallel delta mode)..."

export FTP_PASS
lftp -c "
  set sftp:auto-confirm yes
  set net:max-retries 3
  set net:reconnect-interval-base 5
  set cmd:fail-exit yes
  open -u \"${FTP_USER}\",\"\$FTP_PASS\" \"sftp://${FTP_HOST}\"
  rm -rf \"${REMOTE_DIR}_astro\"
  # 1. Fast sync of large static media folders (--ignore-time skips unchanged files of same size)
  mirror --reverse --delete --ignore-time --parallel=8 --verbose ./dist/ \"${REMOTE_DIR}\"
  # 2. Force-update all HTML, XML, TXT, JSON and .htaccess files (even if byte size did not change)
  mirror --reverse --parallel=8 \
    --include-glob='*.html' \
    --include-glob='*.html.gz' \
    --include-glob='*.xml' \
    --include-glob='*.xml.gz' \
    --include-glob='*.txt' \
    --include-glob='*.txt.gz' \
    --include-glob='*.json' \
    --include-glob='*.webmanifest' \
    --include-glob='.htaccess' \
    --include-glob='_redirects' \
    ./dist/ \"${REMOTE_DIR}\"
  mkdir -p \"${REMOTE_DIR}products/ausgabeschein-generator/\"
  put -O \"${REMOTE_DIR}products/ausgabeschein-generator/\" ./dist/products/ausgabeschein-generator/workbench.png
  put -O \"${REMOTE_DIR}products/ausgabeschein-generator/\" ./dist/products/ausgabeschein-generator/print-preview.png
  put -O \"${REMOTE_DIR}products/ausgabeschein-generator/\" ./dist/products/ausgabeschein-generator/mobile.png
  bye
"

echo "Deployment to https://www.waldheim.dev completed successfully!"
